DROP TABLE IF EXISTS `ert`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ert` (
  `event_id` int NOT NULL AUTO_INCREMENT,
  `citizen_id` int NOT NULL,
  `region_id` int NOT NULL,
  `infra_id` int DEFAULT NULL,
  `event_title` varchar(100) NOT NULL,
  `event_content` text,
  `event_type` varchar(30) NOT NULL,
  `report_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `event_status` tinyint NOT NULL DEFAULT '1',
  PRIMARY KEY (`event_id`),
  KEY `citizen_id` (`citizen_id`),
  KEY `region_id` (`region_id`),
  KEY `infra_id` (`infra_id`),
  CONSTRAINT `ert_ibfk_1` FOREIGN KEY (`citizen_id`) REFERENCES `ct` (`citizen_id`) ON DELETE CASCADE,
  CONSTRAINT `ert_ibfk_2` FOREIGN KEY (`region_id`) REFERENCES `rt` (`region_id`) ON DELETE RESTRICT,
  CONSTRAINT `ert_ibfk_3` FOREIGN KEY (`infra_id`) REFERENCES `it` (`infra_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
